with valid as (select id, order_id, method, paid_at, case when status = 'SUCCESS' then 1 else 0 end as is_success, case when method = 'paypal' then 1 else 0 end as is_paypal from payments where paid_at > date '2024-04-20' and method is not null and method in ('paypal', 'cash', 'promptpay')) select *, sum(is_success) over (partition by order_id order by paid_at, id rows between unbounded preceding and current row) as running_is_success, ntile(10) over (partition by method order by is_paypal, id) as is_paypal_bucket from valid;
